@import url("https://fonts.googleapis.com/css2?family=Barlow+Semi+Condensed:wght@600;700;800&family=Outfit:wght@400;500;600;700;800&display=swap");
.fls-b{--navy:#0A1A33;--navy2:#0E2A4F;--navy3:#133A6B;--blue:#0090D8;--blue2:#38B6EF;--soft:#E8F5FD;--red:#E63312;--red2:#B81F05;--ink:#15222F;--mut:#5A6E82;--line:#E2E9F1;--bg:#F4F8FC;--gut:20px;
 font-family:Outfit,system-ui,Arial,sans-serif;color:var(--ink);line-height:1.65;font-size:16.5px;-webkit-font-smoothing:antialiased;background:#fff;overflow-x:clip}
.fls-b *,.fls-b *::before,.fls-b *::after{box-sizing:border-box;margin:0;padding:0}
.fls-b svg{width:18px;height:18px;flex-shrink:0}
.fls-b img{max-width:100%;display:block;height:auto}
.fls-b a{color:inherit;text-decoration:none}
.fls-b h1,.fls-b h2,.fls-b h3{font-family:Outfit,system-ui,sans-serif;font-weight:800;color:var(--navy);line-height:1.1;letter-spacing:-.025em}
.fls-b h1{font-size:clamp(2.1rem,4.2vw,3.6rem)}
.fls-b h2{font-size:clamp(1.7rem,2.8vw,2.4rem)}
.fls-b h3{font-size:1.18rem;font-weight:700;line-height:1.28;letter-spacing:-.01em}
.fls-b p{overflow-wrap:anywhere}
.fls-b .wrap{max-width:1400px;margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
.fls-b .eyebrow{display:inline-flex;align-items:center;gap:.55rem;font-family:'Barlow Semi Condensed',sans-serif;font-weight:700;font-size:1rem;letter-spacing:.2em;text-transform:uppercase;color:var(--blue);margin-bottom:.6rem}
.fls-b .eyebrow::before{content:"";width:26px;height:3px;border-radius:2px;background:var(--red)}

/* buttons */
.fls-b .btn{position:relative;overflow:hidden;isolation:isolate;display:inline-flex;align-items:center;justify-content:center;gap:.6rem;font-family:'Barlow Semi Condensed',sans-serif;font-weight:700;font-size:1.08rem;letter-spacing:.05em;text-transform:uppercase;border:0;border-radius:999px;padding:.95rem 1.7rem;cursor:pointer;transition:background .2s,transform .2s,box-shadow .2s;white-space:nowrap;line-height:1.2}
.fls-b .btn::before{content:"";position:absolute;top:0;left:-140%;width:55%;height:100%;z-index:-1;background:linear-gradient(90deg,transparent,rgba(255,255,255,.38),transparent);transform:skewX(-22deg);transition:left .65s cubic-bezier(.4,0,.2,1)}
.fls-b .btn:hover{transform:translateY(-2px)}
.fls-b .btn:hover::before{left:150%}
.fls-b .btn svg{width:17px;height:17px;transition:transform .28s}
.fls-b .btn:hover svg{transform:translateX(4px)}
.fls-b .btn-red{background:var(--red);color:#fff;box-shadow:0 10px 24px rgba(230,51,18,.3)}
.fls-b .btn-red:hover{background:var(--red2)}
.fls-b .btn-wht{background:rgba(255,255,255,.08);color:#fff;border:2px solid rgba(255,255,255,.34)}
.fls-b .btn-wht:hover{background:#fff;color:var(--navy)}
.fls-b .btn-wht:hover svg{transform:none}

/* ---------- hero ---------- */
.fls-b .b-hero{padding:28px 0 0}
.fls-b .b-hbox{position:relative;border-radius:30px;overflow:hidden;background:linear-gradient(140deg,var(--navy) 0%,#07162B 55%,var(--navy2) 100%);box-shadow:0 30px 70px rgba(10,26,51,.22)}
.fls-b .b-hbox::before{content:"";position:absolute;inset:0;opacity:.07;
 background-image:repeating-linear-gradient(0deg,#fff 0 1.5px,transparent 1.5px 74px),repeating-linear-gradient(90deg,#fff 0 1.5px,transparent 1.5px 74px)}
.fls-b .b-hbox::after{content:"";position:absolute;right:-10%;top:-50%;width:60%;height:200%;background:radial-gradient(circle,rgba(0,144,216,.32),transparent 62%)}
.fls-b .b-hin{position:relative;z-index:2;display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,.8fr);gap:48px;align-items:center;padding:62px 64px 66px}
.fls-b .b-hin>*{min-width:0}
.fls-b .b-crumb{display:flex;align-items:center;gap:.5rem;flex-wrap:wrap;font-size:.88rem;color:#9FBCD6;margin-bottom:1.3rem}
.fls-b .b-crumb a{color:#C6DCEF;font-weight:600}
.fls-b .b-crumb a:hover{color:#fff}
.fls-b .b-crumb svg{width:13px;height:13px;color:#5E7E9C}
.fls-b .b-crumb span[aria-current]{color:#fff;font-weight:600}
.fls-b .b-hero .eyebrow{color:var(--blue2)}
.fls-b .b-hero h1{color:#fff}
.fls-b .b-hero h1 em{font-style:normal;color:var(--blue2);display:block}
.fls-b .b-hero .sub{font-size:1.1rem;color:#C6DCEF;margin:1.15rem 0 1.6rem;max-width:36rem;line-height:1.7}
.fls-b .b-stats{display:flex;flex-wrap:wrap;gap:.55rem}
.fls-b .b-stats span{display:inline-flex;align-items:center;gap:.45rem;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.18);padding:.46rem 1rem;border-radius:999px;font-size:.88rem;font-weight:600;color:#fff}
.fls-b .b-stats svg{width:15px;height:15px;color:var(--blue2)}
.fls-b .b-stats b{color:var(--blue2);font-weight:800}
.fls-b .b-quick{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.16);border-radius:20px;padding:24px 24px 18px;backdrop-filter:blur(8px)}
.fls-b .b-quick h2{color:#fff;font-size:1.04rem;letter-spacing:.14em;text-transform:uppercase;font-weight:800;margin-bottom:.8rem;display:flex;align-items:center;gap:.6rem}
.fls-b .b-quick h2::before{content:"";width:22px;height:3px;border-radius:2px;background:var(--red)}
.fls-b .b-quick ul{list-style:none}
.fls-b .b-quick li{border-bottom:1px solid rgba(255,255,255,.12)}
.fls-b .b-quick li:last-child{border-bottom:0}
.fls-b .b-quick a{display:flex;align-items:center;justify-content:space-between;gap:.8rem;padding:.78rem 0;color:#E4EEF7;font-weight:600;font-size:.98rem;line-height:1.35;transition:color .2s}
.fls-b .b-quick a svg{width:16px;height:16px;color:var(--blue2);transition:transform .25s}
.fls-b .b-quick a:hover{color:#fff}
.fls-b .b-quick a:hover svg{transform:translateX(4px)}

/* ---------- filters ---------- */
.fls-b .b-list{padding:70px 0 84px}
.fls-b .b-head{display:flex;align-items:flex-end;justify-content:space-between;gap:1.5rem;flex-wrap:wrap;margin-bottom:1.6rem}
.fls-b .b-head p{color:var(--mut);max-width:34rem}
.fls-b .bf{position:absolute;opacity:0;width:0;height:0;pointer-events:none}
.fls-b .bf-tabs{display:flex;flex-wrap:wrap;gap:.5rem;margin-bottom:2.2rem;padding-bottom:1.6rem;border-bottom:1px solid var(--line)}
.fls-b .bf-tabs label{display:inline-flex;align-items:center;gap:.5rem;font-family:'Barlow Semi Condensed',sans-serif;font-weight:700;text-transform:uppercase;letter-spacing:.06em;font-size:1rem;padding:.58rem 1.15rem;border-radius:999px;border:1.5px solid var(--line);background:#fff;color:var(--navy);cursor:pointer;transition:.2s;user-select:none}
.fls-b .bf-tabs label i{font-style:normal;font-family:Outfit,sans-serif;font-size:.78rem;font-weight:700;letter-spacing:0;min-width:24px;height:22px;padding:0 6px;border-radius:999px;background:var(--bg);color:var(--mut);display:inline-flex;align-items:center;justify-content:center}
.fls-b .bf-tabs label:hover{border-color:var(--blue);color:var(--blue)}
.fls-b .f-all:checked~.bf-tabs label[for=fls-bf-all],
.fls-b .f-leaks:checked~.bf-tabs label[for=fls-bf-leaks],
.fls-b .f-mould:checked~.bf-tabs label[for=fls-bf-mould],
.fls-b .f-diy:checked~.bf-tabs label[for=fls-bf-diy],
.fls-b .f-wp:checked~.bf-tabs label[for=fls-bf-wp],
.fls-b .f-costs:checked~.bf-tabs label[for=fls-bf-costs]{background:var(--navy);border-color:var(--navy);color:#fff}
.fls-b .f-all:checked~.bf-tabs label[for=fls-bf-all] i,
.fls-b .f-leaks:checked~.bf-tabs label[for=fls-bf-leaks] i,
.fls-b .f-mould:checked~.bf-tabs label[for=fls-bf-mould] i,
.fls-b .f-diy:checked~.bf-tabs label[for=fls-bf-diy] i,
.fls-b .f-wp:checked~.bf-tabs label[for=fls-bf-wp] i,
.fls-b .f-costs:checked~.bf-tabs label[for=fls-bf-costs] i{background:var(--red);color:#fff}
.fls-b .f-leaks:checked~.bgrid .bcard:not([data-c~="leaks"]),
.fls-b .f-mould:checked~.bgrid .bcard:not([data-c~="mould"]),
.fls-b .f-diy:checked~.bgrid .bcard:not([data-c~="diy"]),
.fls-b .f-wp:checked~.bgrid .bcard:not([data-c~="wp"]),
.fls-b .f-costs:checked~.bgrid .bcard:not([data-c~="costs"]){display:none}
/* the featured card collapses to a normal card inside a filtered view */
.fls-b .f-leaks:checked~.bgrid .bcard.feat{grid-column:auto;display:flex;flex-direction:column}
.fls-b .f-leaks:checked~.bgrid .bcard.feat .bimg{aspect-ratio:16/10;min-height:0}
.fls-b .f-leaks:checked~.bgrid .bcard.feat .bbody{padding:20px 22px 22px}
.fls-b .f-leaks:checked~.bgrid .bcard.feat h3{font-size:1.18rem}
.fls-b .f-leaks:checked~.bgrid .bcard.feat .bstart{display:none}

/* show the primary badge by default, and the matching badge inside a filtered view */
.fls-b .btag{display:none}
.fls-b .btag.prim{display:inline-block}
.fls-b .f-leaks:checked~.bgrid .btag,.fls-b .f-mould:checked~.bgrid .btag,.fls-b .f-diy:checked~.bgrid .btag,.fls-b .f-wp:checked~.bgrid .btag,.fls-b .f-costs:checked~.bgrid .btag{display:none}
.fls-b .f-leaks:checked~.bgrid .btag.leaks,.fls-b .f-mould:checked~.bgrid .btag.mould,.fls-b .f-diy:checked~.bgrid .btag.diy,.fls-b .f-wp:checked~.bgrid .btag.wp,.fls-b .f-costs:checked~.bgrid .btag.costs{display:inline-block}

/* ---------- cards ---------- */
.fls-b .bgrid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:26px}
.fls-b .bcard{position:relative;display:flex;flex-direction:column;background:#fff;border:1px solid var(--line);border-radius:20px;overflow:hidden;min-width:0;transition:transform .28s,box-shadow .28s,border-color .28s}
.fls-b .bcard:hover{transform:translateY(-6px);box-shadow:0 26px 52px rgba(10,26,51,.14);border-color:transparent}
.fls-b .bimg{position:relative;aspect-ratio:16/10;overflow:hidden;background:var(--bg)}
.fls-b .bimg img{width:100%;height:100%;object-fit:cover;transition:transform .6s cubic-bezier(.2,.7,.2,1)}
.fls-b .bcard:hover .bimg img{transform:scale(1.06)}
.fls-b .bimg .btag{position:absolute;left:14px;top:14px;z-index:2;background:rgba(10,26,51,.88);color:#fff;font-family:'Barlow Semi Condensed',sans-serif;font-weight:700;font-size:.82rem;letter-spacing:.1em;text-transform:uppercase;padding:.3rem .75rem;border-radius:999px;backdrop-filter:blur(4px)}
.fls-b .bimg .btag.leaks{background:rgba(230,51,18,.92)}
.fls-b .bimg .btag.costs{background:rgba(0,144,216,.92)}
.fls-b .bbody{display:flex;flex-direction:column;flex:1;padding:20px 22px 22px}
.fls-b .bmeta{display:flex;flex-wrap:wrap;gap:.35rem 1rem;font-size:.82rem;color:var(--mut);margin-bottom:.6rem}
.fls-b .bmeta span{display:inline-flex;align-items:center;gap:.35rem}
.fls-b .bmeta svg{width:14px;height:14px;color:var(--blue)}
.fls-b .bcard h3{margin-bottom:.5rem}
.fls-b .bcard h3 a::after{content:"";position:absolute;inset:0;z-index:3}
.fls-b .bcard h3 a:focus-visible{outline:none}
.fls-b .bcard:focus-within{outline:3px solid var(--blue2);outline-offset:3px}
.fls-b .bcard p{color:var(--mut);font-size:.94rem;line-height:1.62;display:-webkit-box;-webkit-line-clamp:3;line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.fls-b .bmore{display:inline-flex;align-self:flex-start;align-items:center;gap:.4rem;margin-top:auto;padding-top:1rem;font-family:'Barlow Semi Condensed',sans-serif;font-weight:700;letter-spacing:.06em;text-transform:uppercase;font-size:.98rem;color:var(--red)}
.fls-b .bmore svg{width:15px;height:15px;transition:transform .25s}
.fls-b .bcard:hover .bmore svg{transform:translateX(5px)}

/* featured card spans the row */
.fls-b .bcard.feat{grid-column:1/-1;display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,1fr);border-radius:24px}
.fls-b .bcard.feat .bimg{aspect-ratio:auto;min-height:380px}
.fls-b .bcard.feat .bbody{padding:40px 44px;justify-content:center}
.fls-b .bcard.feat h3{font-size:clamp(1.5rem,2.4vw,2.15rem);font-weight:800;letter-spacing:-.025em;line-height:1.12;margin-bottom:.8rem}
.fls-b .bcard.feat p{font-size:1.04rem;-webkit-line-clamp:4;line-clamp:4}
.fls-b .bcard.feat .bmore{margin-top:0;padding-top:1.3rem}
.fls-b .bstart{display:inline-flex;align-self:flex-start;align-items:center;gap:.45rem;background:var(--soft);color:var(--blue);font-family:'Barlow Semi Condensed',sans-serif;font-weight:700;letter-spacing:.12em;text-transform:uppercase;font-size:.88rem;padding:.35rem .85rem;border-radius:999px;margin-bottom:1rem}
.fls-b .bstart svg{width:14px;height:14px}

/* ---------- cta ---------- */
.fls-b .b-cta-sec{padding:0 0 90px}
.fls-b .b-cta{position:relative;overflow:hidden;border-radius:26px;background:linear-gradient(118deg,var(--navy3),var(--navy));padding:56px 48px;color:#fff;display:grid;grid-template-columns:minmax(0,1.3fr) auto;gap:32px;align-items:center}
.fls-b .b-cta::after{content:"";position:absolute;right:-8%;top:-60%;width:46%;height:220%;background:radial-gradient(circle,rgba(0,144,216,.36),transparent 62%)}
.fls-b .b-cta>*{position:relative;z-index:2;min-width:0}
.fls-b .b-cta .eyebrow{color:#7FD2F7}
.fls-b .b-cta h2{color:#fff}
.fls-b .b-cta p{color:#C3D9EC;margin-top:.7rem;max-width:40rem}
.fls-b .b-cta .row{display:flex;gap:.8rem;flex-wrap:wrap;justify-content:flex-end}

/* reveal */
.fls-b .rv{animation:flsbIn .8s both}
.fls-b .rv2{animation-delay:.12s}
@keyframes flsbIn{from{opacity:0;transform:translateY(22px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){.fls-b .rv{animation:none}.fls-b .bcard,.fls-b .bimg img{transition:none}}
.fls-b a:focus-visible,.fls-b label:focus-visible{outline:3px solid var(--blue2);outline-offset:3px}

/* ---------- responsive ---------- */
@media(max-width:1180px){
 .fls-b .b-hin{grid-template-columns:1fr;gap:34px;padding:52px 44px 54px}
 .fls-b .bgrid{grid-template-columns:repeat(2,minmax(0,1fr))}
 .fls-b .b-cta{grid-template-columns:1fr}
 .fls-b .b-cta .row{justify-content:flex-start}
}
@media(max-width:860px){
 .fls-b .bcard.feat{grid-template-columns:1fr}
 .fls-b .bcard.feat .bimg{min-height:0;aspect-ratio:16/9}
 .fls-b .bcard.feat .bbody{padding:26px 24px 28px}
}
@media(max-width:640px){
 .fls-b{--gut:16px}
 .fls-b .b-hero{padding-top:14px}
 .fls-b .b-hbox{border-radius:20px}
 .fls-b .b-hin{padding:38px 22px 40px}
 .fls-b .bgrid{grid-template-columns:1fr;gap:20px}
 .fls-b .b-list{padding:50px 0 60px}
 .fls-b .bf-tabs{flex-wrap:nowrap;overflow-x:auto;margin-left:calc(-1 * var(--gut));margin-right:calc(-1 * var(--gut));padding-left:var(--gut);padding-right:var(--gut);scrollbar-width:none}
 .fls-b .bf-tabs::-webkit-scrollbar{display:none}
 .fls-b .bf-tabs label{flex:none}
 .fls-b .b-cta{padding:38px 22px;border-radius:20px}
 .fls-b .b-cta .row .btn{width:100%}
 .fls-b .btn{white-space:normal;text-align:center}
 .fls-b .b-cta-sec{padding-bottom:60px}
}
